gaOw(){return"\u0646\u0638\u0631\u0629 \u0633\u0631\u064a\u0639\u0629 \u0639\u0644\u0649 \u0623\u0631\u0635\u062f\u0629 \u0625\u062c\u0627\u0632\u0627\u062a\u0643. \xab\u0627\u0644\u0645\u062a\u0627\u062d \u0627\u0644\u0622\u0646\xbb \u0647\u0648 \u0645\u0627 \u064a\u0645\u0643\u0646\u0643 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647 \u0627\u0644\u064a\u0648\u0645 (\u0648\u0642\u062f \u064a\u0635\u0628\u062d \u0633\u0627\u0644\u0628\u064b\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0644\u062f\u064a\u0643 \u0639\u062c\u0632). \u0623\u064a\u0627\u0645 \u0627\u0644\u062a\u0631\u062d\u064a\u0644 \u0647\u064a \u0631\u0635\u064a\u062f \u0627\u0644\u0639\u0627\u0645 \u0627\u0644\u0633\u0627\u0628\u0642 \u0648\u062a\u0646\u062a\u0647\u064a \u0641\u064a 1 \u0623\u0628\u0631\u064a\u0644\u060c \u0648\u064a\u064f\u0639\u0631\u0636 \u0631\u0635\u064a\u062f \u0627\u0644\u0623\u0648\u0641\u0631\u062a\u0627\u064a\u0645/\u0627\u0644\u062a\u0639\u0648\u064a\u0636\u064a \u0628\u0634\u0643\u0644 \u0645\u0646\u0641\u0635\u0644 \u0648\u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u0642\u0628\u0644 \u0627\u0644\u0625\u062c\u0627\u0632\u0629 \u0627\u0644\u0633\u0646\u0648\u064a\u0629."},
gaOD(){return"\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0628\u062f\u0627\u064a\u0629"},
gaOC(){return"\u0627\u062e\u062a\u0631 \u0623\u0648\u0644 \u064a\u0648\u0645 \u0644\u0625\u062c\u0627\u0632\u062a\u0643. \u0641\u064a \u0627\u0644\u062a\u0642\u0648\u064a\u0645\u060c \u0627\u0644\u0623\u064a\u0627\u0645 \u0627\u0644\u0645\u0634\u0637\u0648\u0628\u0629 \u0628\u0627\u0644\u0644\u0648\u0646 \u0627\u0644\u0623\u062d\u0645\u0631 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629 \u0644\u0648\u062c\u0648\u062f \u0637\u0644\u0628 \u0625\u062c\u0627\u0632\u0629 \u0623\u0648 \u0645\u0623\u0645\u0648\u0631\u064a\u0629 \u0623\u0648 \u0628\u0635\u0645\u0629 \u0646\u0627\u0642\u0635\u0629 \u0639\u0644\u064a\u0647\u0627. \u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0623\u062d\u0645\u0631 \u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0633\u0628\u0628."},
gaOJ(){return"\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0646\u0647\u0627\u064a\u0629"},
gaOI(){return"\u0627\u062e\u062a\u0631 \u0622\u062e\u0631 \u064a\u0648\u0645 \u0644\u0625\u062c\u0627\u0632\u062a\u0643. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0623\u0646 \u062a\u0645\u062a\u062f \u0627\u0644\u0641\u062a\u0631\u0629 \u0639\u0628\u0631 \u064a\u0648\u0645 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d (\u0623\u062d\u0645\u0631)\u060c \u0644\u0630\u0627 \u062a\u062a\u063a\u064a\u0651\u0631 \u0627\u0644\u0623\u064a\u0627\u0645 \u0627\u0644\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0627\u062e\u062a\u064a\u0627\u0631 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0628\u062f\u0627\u064a\u0629."},
gaOF(){return"\u0633\u0627\u0639\u0627\u062a \u062c\u0632\u0626\u064a\u0629"},
gaOE(){return"\u064a\u0638\u0647\u0631 \u0641\u0642\u0637 \u0644\u0637\u0644\u0628 \u0644\u064a\u0648\u0645 \u0648\u0627\u062d\u062f. \u0627\u062e\u062a\u0631 \u0639\u062f\u062f \u0627\u0644\u0633\u0627\u0639\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u062d\u062a\u0627\u062c\u0647\u0627 \u0628\u062f\u0644\u064b\u0627 \u0645\u0646 \u064a\u0648\u0645 \u0643\u0627\u0645\u0644 \u2014 \u0627\u062a\u0631\u0643\u0647 \u0641\u0627\u0631\u063a\u064b\u0627 \u0644\u0623\u062e\u0630 \u0627\u0644\u064a\u0648\u0645 \u0643\u0627\u0645\u0644\u064b\u0627. \u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u0633\u0627\u0639\u0627\u062a \u064a\u062d\u062f\u0651\u062f \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0625\u062c\u0627\u0632\u0627\u062a \u0627\u0644\u0645\u062a\u0627\u062d\u0629."},
gaOB(){return"\u0623\u064a\u0627\u0645 \u0627\u0644\u063a\u064a\u0627\u0628"},
gaOA(){return"\u0639\u062f\u0651\u0627\u062f \u0645\u0628\u0627\u0634\u0631 \u0644\u0645\u062f\u0629 \u063a\u064a\u0627\u0628\u0643 \u062d\u0633\u0628 \u0627\u0644\u062a\u0648\u0627\u0631\u064a\u062e \u0627\u0644\u0645\u062e\u062a\u0627\u0631\u0629. \u064a\u0639\u0631\u0636 \u0627\u0644\u0633\u0627\u0639\u0627\u062a \u0628\u062f\u0644 \u0627\u0644\u0623\u064a\u0627\u0645 \u0639\u0646\u062f \u0637\u0644\u0628 \u0633\u0627\u0639\u0627\u062a \u062c\u0632\u0626\u064a\u0629."},
gaOL(){return"\u0646\u0648\u0639 \u0627\u0644\u0625\u062c\u0627\u0632\u0629"},
gaOK(){return"\u0627\u062e\u062a\u0631 \u0627\u0644\u0646\u0648\u0639 \u0627\u0644\u0645\u0646\u0627\u0633\u0628 \u0644\u062d\u0627\u0644\u062a\u0643. \u0627\u0644\u062e\u064a\u0627\u0631 \u0627\u0644\u0628\u0627\u0647\u062a \u064a\u0639\u0646\u064a \u0623\u0646\u0651 \u0634\u0631\u0637\u0647 \u063a\u064a\u0631 \u0645\u062d\u0642\u0651\u0642 \u0644\u062a\u0648\u0627\u0631\u064a\u062e\u0643 \u0623\u0648 \u0633\u0627\u0639\u0627\u062a\u0643 \u0623\u0648 \u0631\u0635\u064a\u062f\u0643 \u0627\u0644\u062d\u0627\u0644\u064a.\n\n\u2022 \u0633\u0646\u0648\u064a\u0629 \u2014 \u0625\u062c\u0627\u0632\u0629 \u0645\u062e\u0637\u0651\u0637\u0629. \u062a\u062a\u0637\u0644\u0651\u0628 \u0631\u0635\u064a\u062f\u064b\u0627 \u0645\u062a\u0627\u062d\u064b\u0627 \u0623\u0648 \u0645\u0631\u062d\u0651\u0644\u064b\u0627\u060c \u0648\u062a\u062e\u0636\u0639 \u0644\u062d\u062f\u0651\u0643 \u0627\u0644\u0633\u0646\u0648\u064a \u0648\u0625\u0646 \u0643\u0627\u0646 \u0644\u062f\u064a\u0643 \u0631\u0635\u064a\u062f \u0623\u0648\u0641\u0631\u062a\u0627\u064a\u0645 \u0641\u0627\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u062a\u0639\u0648\u064a\u0636\u064a\u0629 \u0623\u0648\u0644\u064b\u0627.\n\n\u2022 \u0637\u0627\u0631\u0626\u0629 \u2014 \u0644\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0645\u0641\u0627\u062c\u0626\u0629 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u064a\u0648\u0645. \u0645\u062d\u062f\u0648\u062f\u0629 \u0628\u064a\u0648\u0645 \u0648\u0627\u062d\u062f \u0648\u062a\u062a\u0637\u0644\u0651\u0628 \u0631\u0635\u064a\u062f\u064b\u0627 \u0633\u0646\u0648\u064a\u064b\u0627/\u0645\u0631\u062d\u0651\u0644\u064b\u0627 \u0645\u062a\u0627\u062d\u064b\u0627.\n\n\u2022 \u062a\u0639\u0648\u064a\u0636\u064a\u0629 \u2014 \u062a\u064f\u062e\u0635\u0645 \u0645\u0646 \u0631\u0635\u064a\u062f \u0627\u0644\u0623\u0648\u0641\u0631\u062a\u0627\u064a\u0645. \u0645\u062a\u0627\u062d\u0629 \u0641\u0642\u0637 \u0639\u0646\u062f\u0645\u0627 \u064a\u063a\u0637\u0651\u064a \u0630\u0644\u0643 \u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0623\u064a\u0627\u0645 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629.\n\n\u2022 \u0645\u0631\u0636\u064a\u0629 \u2014 \u0644\u0644\u0645\u0631\u0636. \u062a\u062a\u0637\u0644\u0651\u0628 \u0631\u0641\u0639 \u062a\u0642\u0631\u064a\u0631 \u0637\u0628\u064a.\n\n\u2022 \u0628\u062f\u0648\u0646 \u0623\u062c\u0631 \u2014 \u0625\u062c\u0627\u0632\u0629 \u062f\u0648\u0646 \u0631\u0627\u062a\u0628. \u0645\u062a\u0627\u062d\u0629 \u0641\u0642\u0637 \u0639\u0646\u062f\u0645\u0627 \u064a\u0643\u0648\u0646 \u0631\u0635\u064a\u062f\u0643 \u0627\u0644\u0645\u062f\u0641\u0648\u0639 \u0636\u0626\u064a\u0644\u064b\u0627 \u0623\u0648 \u0645\u0646\u0639\u062f\u0645\u064b\u0627."},
gaOH(){return"\u0627\u0644\u0625\u0631\u0633\u0627\u0644"},
gaOG(){return"\u064a\u0631\u0633\u0644 \u0637\u0644\u0628\u0643 \u0644\u0644\u0627\u0639\u062a\u0645\u0627\u062f. \u064a\u0628\u0642\u0649 \u0627\u0644\u0632\u0631 \u0631\u0645\u0627\u062f\u064a\u064b\u0627 \u0648\u0645\u0639\u0637\u0651\u0644\u064b\u0627 \u062d\u062a\u0649 \u062a\u0643\u062a\u0645\u0644 \u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u0642\u0648\u0644 \u0628\u0634\u0643\u0644 \u0635\u062d\u064a\u062d \u062b\u0645 \u064a\u062a\u062d\u0648\u0651\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0632\u0631\u0642. \u0648\u062a\u0638\u0647\u0631 \u0623\u064a \u0645\u0634\u0643\u0644\u0629 \u0645\u0627\u0646\u0639\u0629 (\u0645\u062b\u0644 \u0637\u0644\u0628 \u0637\u0627\u0631\u0626 \u0623\u0637\u0648\u0644 \u0645\u0646 \u0627\u0644\u0645\u0633\u0645\u0648\u062d) \u0623\u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0632\u0631 \u0645\u0628\u0627\u0634\u0631\u0629."},
